import 'package:cloud_firestore/cloud_firestore.dart';
import '../business/business_repository.dart';
import '../goals/goal_repository.dart';
class AurenPartnershipMatch{final String businessId,name,category,city,country,reason;final int signals;const AurenPartnershipMatch({required this.businessId,required this.name,required this.category,required this.city,required this.country,required this.reason,required this.signals});}
class PartnershipMatcherService{final BusinessRepository businesses;final GoalRepository goals;PartnershipMatcherService({BusinessRepository? businesses,GoalRepository? goals}):businesses=businesses??BusinessRepository(),goals=goals??GoalRepository();
Future<List<AurenPartnershipMatch>> find(String uid,{String query=''})async{final all=await businesses.watchPublic().first;final own=all.where((b)=>b.ownerId==uid).map((b)=>b.id).toSet();final gs=await goals.watch(uid).first;final terms=<String>{...query.toLowerCase().split(RegExp(r'\s+')).where((x)=>x.length>2),...gs.where((g)=>g.status=='active').expand((g)=>g.title.toLowerCase().split(RegExp(r'\s+'))).where((x)=>x.length>2)};final out=<AurenPartnershipMatch>[];for(final b in all){if(own.contains(b.id))continue;final hay=[b.name,b.description,b.category,b.city,b.country,b.businessType].join(' ').toLowerCase();final hits=terms.where(hay.contains).length;final sameCategory=terms.isEmpty?false:terms.any((t)=>b.category.toLowerCase().contains(t));final signals=hits+(sameCategory?1:0)+(b.verified?1:0);if(signals>0)out.add(AurenPartnershipMatch(businessId:b.id,name:b.name,category:b.category,city:b.city,country:b.country,reason:hits>0?'تطابق مع سياقك وأهدافك':'تطابق في المجال',signals:signals));}out.sort((a,b)=>b.signals.compareTo(a.signals));return out.take(30).toList();}}